def-struct(
    Algebra.Ring(
        R@Algebra.ctxt.ring, $+$@Algebra.ctxt.ring, $\cdot$@Algebra.ctxt.ring
    ),
    struct(
        Algebra.Abelian(R@Algebra.ctxt.ring, $+$@Algebra.ctxt.ring),
        Algebra.Semigroup(R@Algebra.ctxt.ring, $\cdot$@Algebra.ctxt.ring),
        Logic.forall-typed(
            list-partial(@a, @b, @c),
            R@Algebra.ctxt.ring,
            Logic.and(
                Eq(
                    Bop.apply($\cdot$@Algebra.ctxt.ring, a, Bop.apply[paren]($+$@Algebra.ctxt.ring, b, c)),
                    Bop.apply($+$@Algebra.ctxt.ring, Bop.apply($\cdot$@Algebra.ctxt.ring, a, b), Bop.apply($\cdot$@Algebra.ctxt.ring, a, c))
                ),
                Eq(
                    Bop.apply($\cdot$@Algebra.ctxt.ring, Bop.apply[paren]($+$@Algebra.ctxt.ring, a, b), c),
                    Bop.apply($+$@Algebra.ctxt.ring, Bop.apply($\cdot$@Algebra.ctxt.ring, a, c), Bop.apply($\cdot$@Algebra.ctxt.ring, b, c))
                )
            )
        )
    )
)
